1	//! `MessageTranslator` — Anthropic SSE events → `ModelEvent` stream.
2	
3	use std::collections::HashMap;
4	
5	use paigasus_helikon_core::{FinishReason, ModelError, ModelEvent};
6	
7	use crate::error::map_error_type;
8	use crate::sse::{
9	    AnthropicEvent, ContentBlockDelta, ContentBlockHead, MessageDeltaUsage, MessageStartUsage,
10	};
11	use crate::translate::response_format::SYNTHESIZED_TOOL_NAME;
12	
13	#[derive(Debug)]
14	enum BlockState {
15	    Text,
16	    Thinking,
17	    ToolUse {
18	        call_id: String,
19	        name: String,
20	        name_emitted: bool,
21	    },
22	}
23	
24	/// State machine for one streaming response.
25	///
26	/// `synthesizing_output: true` means a `ResponseFormat::JsonSchema`/`JsonObject`
27	/// request was sent. When the synthesized tool's content block starts, its
28	/// `input_json_delta` events are remapped to `TokenDelta`s and the
29	/// `stop_reason: "tool_use"` is rewritten to `Stop` if it was the only tool fired.
30	pub(crate) struct MessageTranslator {
31	    blocks: HashMap<u32, BlockState>,
32	    last_input_tokens: u32,
33	    last_cached_input_tokens: Option<u32>,
34	    stop_reason: Option<String>,
35	    synthesizing_output: bool,
36	    synthesized_tool_index: Option<u32>,
37	    other_tool_fired: bool,
38	    terminal_emitted: bool,
39	}
40	
41	impl MessageTranslator {
42	    pub(crate) fn new(synthesizing_output: bool) -> Self {
43	        Self {
44	            blocks: HashMap::new(),
45	            last_input_tokens: 0,
46	            last_cached_input_tokens: None,
47	            stop_reason: None,
48	            synthesizing_output,
49	            synthesized_tool_index: None,
50	            other_tool_fired: false,
51	            terminal_emitted: false,
52	        }
53	    }
54	
55	    /// Consume one event. Returns the emitted ModelEvents (most calls
56	    /// emit zero or one; `message_delta` carrying both stop_reason and
57	    /// usage emits one Usage followed by Finish on `message_stop`). A
58	    /// terminal event (`Finish` or an `Err`) is emitted at most once per
59	    /// stream, and a later `message_delta`'s `Usage` is suppressed once one
60	    /// has been emitted. Content deltas are deliberately *not* guarded: a
61	    /// malformed stream that keeps sending `content_block_delta` after
62	    /// `message_stop` would still yield them. A clean end-of-stream flush of
63	    /// a buffered stop reason with no terminal event yet is handled
64	    /// separately by `finish()`.
65	    pub(crate) fn consume(
66	        &mut self,
67	        event: AnthropicEvent,
68	    ) -> Result<Vec<Result<ModelEvent, ModelError>>, ModelError> {
69	        let mut out: Vec<Result<ModelEvent, ModelError>> = Vec::new();
70	        match event {
71	            AnthropicEvent::MessageStart { message } => {
72	                let MessageStartUsage {
73	                    input_tokens,
74	                    cache_read_input_tokens,
75	                    ..
76	                } = message.usage;
77	                self.last_input_tokens = input_tokens;
78	                self.last_cached_input_tokens = cache_read_input_tokens;
79	                out.push(Ok(ModelEvent::Usage {
80	                    input_tokens,
81	                    output_tokens: 0,
82	                    cached_input_tokens: cache_read_input_tokens,
83	                    reasoning_tokens: None,
84	                }));
85	            }
86	            AnthropicEvent::ContentBlockStart {
87	                index,
88	                content_block,
89	            } => match content_block {
90	                ContentBlockHead::Text => {
91	                    self.blocks.insert(index, BlockState::Text);
92	                }
93	                ContentBlockHead::Thinking => {
94	                    self.blocks.insert(index, BlockState::Thinking);
95	                }
96	                ContentBlockHead::ToolUse { id, name, .. } => {
97	                    if self.synthesizing_output && name == SYNTHESIZED_TOOL_NAME {
98	                        self.synthesized_tool_index = Some(index);
99	                    } else {
100	                        self.other_tool_fired = true;
101	                    }
102	                    self.blocks.insert(
103	                        index,
104	                        BlockState::ToolUse {
105	                            call_id: id,
106	                            name,
107	                            name_emitted: false,
108	                        },
109	                    );
110	                }
111	            },
112	            AnthropicEvent::ContentBlockDelta { index, delta } => match delta {
113	                ContentBlockDelta::TextDelta { text } => {
114	                    out.push(Ok(ModelEvent::TokenDelta { text }));
115	                }
116	                ContentBlockDelta::ThinkingDelta { thinking } => {
117	                    out.push(Ok(ModelEvent::ReasoningDelta { text: thinking }));
118	                }
119	                ContentBlockDelta::SignatureDelta { .. } => {
120	                    tracing::debug!(
121	                        target: "paigasus::anthropic::stream",
122	                        "signature_delta dropped (round-trip not yet supported)",
123	                    );
124	                }
125	                ContentBlockDelta::InputJsonDelta { partial_json } => {
126	                    let is_synth = Some(index) == self.synthesized_tool_index;
127	                    if is_synth {
128	                        out.push(Ok(ModelEvent::TokenDelta { text: partial_json }));
129	                    } else if let Some(BlockState::ToolUse {
130	                        call_id,
131	                        name,
132	                        name_emitted,
133	                    }) = self.blocks.get_mut(&index)
134	                    {
135	                        let (emit_name, call_id_out) = if *name_emitted {
136	                            (None, call_id.clone())
137	                        } else {
138	                            *name_emitted = true;
139	                            (Some(name.clone()), call_id.clone())
140	                        };
141	                        out.push(Ok(ModelEvent::ToolCallDelta {
142	                            call_id: call_id_out,
143	                            name: emit_name,
144	                            args_delta: partial_json,
145	                        }));
146	                    } else {
147	                        // Protocol violation: input_json_delta only ever
148	                        // applies to a tool_use content block. Surface it
149	                        // rather than silently dropping (which would mask
150	                        // a malformed upstream stream).
151	                        return Err(ModelError::Transport(format!(
152	                            "anthropic stream: input_json_delta at index {index} \
153	                             has no preceding tool_use content_block_start"
154	                        )));
155	                    }
156	                }
157	            },
158	            AnthropicEvent::ContentBlockStop { .. } => {
159	                tracing::debug!(target: "paigasus::anthropic::stream", "content_block_stop");
160	            }
161	            AnthropicEvent::MessageDelta { delta, usage } => {
162	                // A `message_delta` after the terminal event is a protocol
163	                // violation (e.g. a second `message_delta` re-arming
164	                // `stop_reason` post-`message_stop`, see
165	                // `second_message_delta_after_message_stop_does_not_double_finish`).
166	                // Emitting its `Usage` would put an event after `Finish`,
167	                // which the core contract forbids.
168	                if !self.terminal_emitted {
169	                    if let Some(MessageDeltaUsage { output_tokens }) = usage {
170	                        out.push(Ok(ModelEvent::Usage {
171	                            input_tokens: self.last_input_tokens,
172	                            output_tokens,
173	                            cached_input_tokens: self.last_cached_input_tokens,
174	                            reasoning_tokens: None,
175	                        }));
176	                    }
177	                }
178	                if let Some(reason) = delta.stop_reason {
179	                    self.stop_reason = Some(reason);
180	                }
181	            }
182	            AnthropicEvent::MessageStop => {
183	                if let Some(reason) = self.stop_reason.take() {
184	                    if !self.terminal_emitted {
185	                        self.terminal_emitted = true;
186	                        out.push(self.finish_or_error(&reason));
187	                    }
188	                }
189	            }
190	            AnthropicEvent::Ping => {}
191	            AnthropicEvent::Error { error } => {
192	                return Err(map_error_type(None, &error.ty, &error.message, None));
193	            }
194	        }
195	        Ok(out)
196	    }
197	
198	    /// Flush a stop reason buffered from `message_delta` when the response
199	    /// body ends cleanly before `message_stop` arrived.
200	    ///
201	    /// Returns `None` when a terminal event was already emitted — the
202	    /// well-formed path, where `message_stop` drained the buffer — or when no
203	    /// stop reason was ever observed. A stream that ended *before*
204	    /// `message_delta` is never reported as a clean `Stop`; one that ended
205	    /// *after* it is, because `message_delta`'s `stop_reason` is the model's
206	    /// own authoritative decision and `message_stop` is only a frame
207	    /// terminator.
208	    ///
209	    /// `terminal_emitted` — not `stop_reason` being `Some` — is the guard.
210	    /// A second `message_delta` can re-arm the buffer after `message_stop`
211	    /// already emitted, and that must not produce a second terminal event.
212	    ///
213	    /// **Clean-EOF path only.** Never call this on the cancellation or
214	    /// transport-error paths — see `model.rs`.
215	    pub(crate) fn finish(&mut self) -> Option<Result<ModelEvent, ModelError>> {
216	        if self.terminal_emitted {
217	            return None;
218	        }
219	        let reason = self.stop_reason.take()?;
220	        self.terminal_emitted = true;
221	        tracing::warn!(
222	            target: "paigasus::anthropic::stream",
223	            stop_reason = %reason,
224	            "stream body ended without message_stop; flushing buffered stop reason",
225	        );
226	        Some(self.finish_or_error(&reason))
227	    }
228	
229	    fn finish_or_error(&self, reason: &str) -> Result<ModelEvent, ModelError> {
230	        match reason {
231	            "end_turn" | "stop_sequence" => Ok(ModelEvent::Finish {
232	                reason: FinishReason::Stop,
233	            }),
234	            "max_tokens" => Ok(ModelEvent::Finish {
235	                reason: FinishReason::Length,
236	            }),
237	            "tool_use" => {
238	                if self.synthesizing_output && !self.other_tool_fired {
239	                    Ok(ModelEvent::Finish {
240	                        reason: FinishReason::Stop,
241	                    })
242	                } else if self.synthesizing_output && self.other_tool_fired {
243	                    Err(ModelError::Other(anyhow::anyhow!(
244	                        "structured output: model fired both a real tool and the synthesized output tool"
245	                    )))
246	                } else {
247	                    Ok(ModelEvent::Finish {
248	                        reason: FinishReason::ToolCalls,
249	                    })
250	                }
251	            }
252	            "refusal" => Err(ModelError::Refused {
253	                reason: "model refused".to_owned(),
254	            }),
255	            other => Ok(ModelEvent::Finish {
256	                reason: FinishReason::Other(other.to_owned()),
257	            }),
258	        }
259	    }
260	}
