281	    #[test]
282	    fn message_start_emits_initial_usage_with_cached_count() {
283	        let mut t = MessageTranslator::new(false);
284	        let out = t.consume(message_start(100, Some(80))).unwrap();
285	        assert_eq!(out.len(), 1);
286	        match out.into_iter().next().unwrap().unwrap() {
287	            ModelEvent::Usage {
288	                input_tokens,
289	                cached_input_tokens,
290	                output_tokens,
291	                ..
292	            } => {
293	                assert_eq!(input_tokens, 100);
294	                assert_eq!(cached_input_tokens, Some(80));
295	                assert_eq!(output_tokens, 0);
296	            }
297	            _ => panic!("expected Usage"),
298	        }
299	    }
