540	    /// A second `message_delta` re-arms `stop_reason` after `message_stop`
541	    /// already emitted the terminal event. The EOF flush must not turn that
542	    /// into a second `Finish` — `core::Model::invoke` guarantees nothing
543	    /// follows `Finish`.
544	    #[test]
545	    fn second_message_delta_after_message_stop_does_not_double_finish() {
546	        let mut t = MessageTranslator::new(false);
547	        let _ = t.consume(message_start(10, None)).unwrap();
548	        let _ = t
549	            .consume(AnthropicEvent::MessageDelta {
550	                delta: MessageDeltaPayload {
551	                    stop_reason: Some("end_turn".to_owned()),
552	                },
553	                usage: None,
554	            })
555	            .unwrap();
556	        let stop_out = t.consume(AnthropicEvent::MessageStop).unwrap();
557	        assert_eq!(stop_out.len(), 1, "message_stop emits the terminal Finish");
558	
559	        // Protocol violation: a second stop reason after the terminal event.
560	        // A real `message_delta` always carries `usage`, so exercise that
561	        // shape rather than sidestepping it with `usage: None`.
562	        let second_delta_out = t
563	            .consume(AnthropicEvent::MessageDelta {
564	                delta: MessageDeltaPayload {
565	                    stop_reason: Some("max_tokens".to_owned()),
566	                },
567	                usage: Some(MessageDeltaUsage { output_tokens: 99 }),
568	            })
569	            .unwrap();
570	        assert!(
571	            second_delta_out.is_empty(),
572	            "nothing may follow the terminal event, got {second_delta_out:?}"
573	        );
574	        assert!(
575	            t.finish().is_none(),
576	            "a second stop reason must not yield a second terminal event"
577	        );
578	    }
