580	    /// The same guard on the inline path. This case is a pre-existing defect,
581	    /// independent of the EOF flush: today the second `message_stop` emits a
582	    /// second `Finish`.
583	    #[test]
584	    fn repeated_message_stop_emits_one_finish() {
585	        let mut t = MessageTranslator::new(false);
586	        let _ = t.consume(message_start(10, None)).unwrap();
587	        let _ = t
588	            .consume(AnthropicEvent::MessageDelta {
589	                delta: MessageDeltaPayload {
590	                    stop_reason: Some("end_turn".to_owned()),
591	                },
592	                usage: None,
593	            })
594	            .unwrap();
595	        assert_eq!(t.consume(AnthropicEvent::MessageStop).unwrap().len(), 1);
596	
597	        let _ = t
598	            .consume(AnthropicEvent::MessageDelta {
599	                delta: MessageDeltaPayload {
600	                    stop_reason: Some("end_turn".to_owned()),
601	                },
602	                usage: None,
603	            })
604	            .unwrap();
605	        let second_stop = t.consume(AnthropicEvent::MessageStop).unwrap();
606	        assert!(
607	            second_stop.is_empty(),
608	            "a repeated message_stop must not emit a second Finish, got {second_stop:?}"
609	        );
610	    }
