612	    /// The core flush: a stop reason buffered with no `message_stop` following.
613	    #[test]
614	    fn finish_flushes_pending_stop_reason() {
615	        let mut t = MessageTranslator::new(false);
616	        let _ = t.consume(message_start(10, None)).unwrap();
617	        let _ = t
618	            .consume(AnthropicEvent::MessageDelta {
619	                delta: MessageDeltaPayload {
620	                    stop_reason: Some("end_turn".to_owned()),
621	                },
622	                usage: Some(MessageDeltaUsage { output_tokens: 5 }),
623	            })
624	            .unwrap();
625	        match t.finish().expect("a buffered reason must flush") {
626	            Ok(ModelEvent::Finish { reason }) => assert_eq!(reason, FinishReason::Stop),
627	            other => panic!("expected Ok(Finish::Stop), got {other:?}"),
628	        }
629	    }
630	
631	    /// The highest-consequence `Ok` variant: the agent loop will execute tool
632	    /// calls assembled from a stream that was cut short.
633	    #[test]
634	    fn finish_flushes_tool_use_as_tool_calls() {
635	        let mut t = MessageTranslator::new(false);
636	        let _ = t.consume(message_start(10, None)).unwrap();
637	        let _ = t
638	            .consume(AnthropicEvent::MessageDelta {
639	                delta: MessageDeltaPayload {
640	                    stop_reason: Some("tool_use".to_owned()),
641	                },
642	                usage: None,
643	            })
644	            .unwrap();
645	        match t.finish().expect("a buffered reason must flush") {
646	            Ok(ModelEvent::Finish { reason }) => assert_eq!(reason, FinishReason::ToolCalls),
647	            other => panic!("expected Ok(Finish::ToolCalls), got {other:?}"),
648	        }
649	    }
650	
651	    /// Truncation before any stop reason: never reported as a clean `Stop`.
652	    #[test]
653	    fn finish_is_none_when_no_stop_reason_observed() {
654	        let mut t = MessageTranslator::new(false);
655	        let _ = t.consume(message_start(10, None)).unwrap();
656	        let _ = t.consume(AnthropicEvent::ContentBlockStart {
657	            index: 0,
658	            content_block: ContentBlockHead::Text,
659	        });
660	        assert!(
661	            t.finish().is_none(),
662	            "no stop reason was observed; nothing to flush"
663	        );
664	    }
665	
666	    /// The well-formed path: `message_stop` already emitted, so the EOF flush
667	    /// is a no-op — and stays one on a repeated call.
668	    #[test]
669	    fn finish_is_none_after_message_stop_drained_it() {
670	        let mut t = MessageTranslator::new(false);
671	        let _ = t.consume(message_start(10, None)).unwrap();
672	        let _ = t
673	            .consume(AnthropicEvent::MessageDelta {
674	                delta: MessageDeltaPayload {
675	                    stop_reason: Some("end_turn".to_owned()),
676	                },
677	                usage: None,
678	            })
679	            .unwrap();
680	        assert_eq!(t.consume(AnthropicEvent::MessageStop).unwrap().len(), 1);
681	        assert!(
682	            t.finish().is_none(),
683	            "message_stop already emitted the terminal event"
684	        );
685	        assert!(t.finish().is_none(), "finish() must be idempotent");
686	    }
687	
688	    /// A refusal observed before truncation surfaces as an error, not silence.
689	    #[test]
