706	
707	    /// The second `Err` outcome: synthesis mode with both a real and the
708	    /// synthesized tool fired. Mirrors bedrock's
709	    /// `finish_surfaces_both_tools_error_without_metadata`.
710	    #[test]
711	    fn finish_surfaces_both_tools_error() {
