1	//! `AnthropicModel` — public [`Model`] implementation.
2	
3	use async_stream::stream;
4	use async_trait::async_trait;
5	use eventsource_stream::Eventsource;
6	use futures_core::stream::BoxStream;
7	use futures_util::StreamExt;
8	use paigasus_helikon_core::{
9	    CancellationToken, Model, ModelCapabilities, ModelError, ModelEvent, ModelRequest,
10	};
11	
12	use crate::builder::{AnthropicModelBuilder, Config};
13	use crate::error::{map_error_type, parse_retry_after_ms};
14	use crate::http::{build_headers, messages_url};
15	use crate::sse::AnthropicEvent;
16	use crate::stream::MessageTranslator;
17	use crate::translate::build_body;
18	
19	/// Anthropic provider — Messages API.
20	///
21	/// Construct via [`Self::messages`].
22	#[derive(Debug)]
23	pub struct AnthropicModel {
24	    pub(crate) cfg: Config,
25	}
26	
27	impl AnthropicModel {
28	    /// Construct a Messages-API model builder.
29	    pub fn messages(model_id: impl Into<String>) -> AnthropicModelBuilder {
30	        AnthropicModelBuilder::new(model_id)
31	    }
32	
33	    pub(crate) fn from_config(cfg: Config) -> Self {
34	        Self { cfg }
35	    }
36	}
37	
38	#[async_trait]
39	impl Model for AnthropicModel {
40	    async fn invoke(
41	        &self,
42	        request: ModelRequest,
43	        cancel: CancellationToken,
44	    ) -> Result<BoxStream<'static, Result<ModelEvent, ModelError>>, ModelError> {
45	        let prepared = build_body(&self.cfg, &request)?;
46	        let synthesizing = prepared.synthesizing_output;
47	        let headers = build_headers(&self.cfg);
48	        let url = messages_url(&self.cfg);
49	        let client = self.cfg.http.clone();
50	
51	        let s = stream! {
52	            let send_fut = client
53	                .post(&url)
54	                .headers(headers)
55	                .json(&prepared.body)
56	                .send();
57	
58	            let response = tokio::select! {
59	                biased;
60	                _ = cancel.cancelled() => return,
61	                r = send_fut => match r {
62	                    Ok(r) => r,
63	                    Err(e) => {
64	                        yield Err(ModelError::Transport(e.to_string()));
65	                        return;
66	                    }
67	                },
68	            };
69	
70	            let status = response.status();
71	            if !status.is_success() {
72	                let retry_after_ms = parse_retry_after_ms(response.headers());
73	                let body_bytes = response.bytes().await.unwrap_or_default();
74	                let parsed: Result<serde_json::Value, _> = serde_json::from_slice(&body_bytes);
75	                let (ty, message) = parsed
76	                    .as_ref()
77	                    .ok()
78	                    .map(|v| {
79	                        let ty = v
80	                            .get("error")
81	                            .and_then(|e| e.get("type"))
82	                            .and_then(|t| t.as_str())
83	                            .unwrap_or("")
84	                            .to_owned();
85	                        let msg = v
86	                            .get("error")
87	                            .and_then(|e| e.get("message"))
88	                            .and_then(|m| m.as_str())
89	                            .unwrap_or("")
90	                            .to_owned();
91	                        (ty, msg)
92	                    })
93	                    .unwrap_or_else(|| {
94	                        (
95	                            String::new(),
96	                            String::from_utf8_lossy(&body_bytes).into_owned(),
97	                        )
98	                    });
99	                yield Err(map_error_type(Some(status.as_u16()), &ty, &message, retry_after_ms));
100	                return;
101	            }
102	
103	            let mut event_stream = response.bytes_stream().eventsource();
104	            let mut translator = MessageTranslator::new(synthesizing);
105	
106	            loop {
107	                let next = tokio::select! {
108	                    biased;
109	                    _ = cancel.cancelled() => return,
110	                    n = event_stream.next() => n,
111	                };
112	                match next {
113	                    // Stream exhausted normally (clean EOF). Flush a stop
114	                    // reason buffered by `message_delta` when `message_stop`
115	                    // never arrived, so the consumer always sees a terminal
116	                    // event. Deliberately NOT done on the cancellation arm
117	                    // above or the transport-error arm (below).
118	                    None => {
119	                        if let Some(terminal) = translator.finish() {
120	                            yield terminal;
121	                        }
122	                        return;
123	                    }
124	                    Some(Err(e)) => {
125	                        yield Err(ModelError::Transport(e.to_string()));
126	                        return;
127	                    }
128	                    Some(Ok(event)) => {
129	                        let parsed: AnthropicEvent = match serde_json::from_str(&event.data) {
130	                            Ok(p) => p,
131	                            Err(parse_err) => {
132	                                // Log structured metadata only — the raw payload
133	                                // may contain user/model/tool content and must
134	                                // not be written to logs.
135	                                tracing::warn!(
136	                                    target: "paigasus::anthropic::sse",
137	                                    %parse_err,
138	                                    event_len = event.data.len(),
139	                                    event_name = %event.event,
140	                                    "unparseable SSE event payload",
141	                                );
142	                                continue;
143	                            }
144	                        };
145	                        match translator.consume(parsed) {
146	                            Err(e) => {
147	                                yield Err(e);
148	                                return;
149	                            }
150	                            Ok(events) => {
151	                                for ev in events {
152	                                    yield ev;
153	                                }
154	                            }
155	                        }
156	                    }
157	                }
158	            }
159	        };
160	
161	        Ok(Box::pin(s))
162	    }
