177	impl AnthropicModelBuilder {
178	    /// Resolve auth, validate inputs, materialize the [`AnthropicModel`].
179	    pub fn build(self) -> Result<AnthropicModel, crate::BuildError> {
180	        Ok(AnthropicModel::from_config(self.build_config()?))
181	    }
182	}
