1	//! `ToolDef` → Anthropic tool entries for the request body.
2	//!
3	//! Anthropic accepts permissive schemas — no strict-mode rewriting.
4	
5	use paigasus_helikon_core::ToolDef;
6	use serde_json::{json, Value};
7	
8	use crate::PROVIDER_ID;
9	
10	/// Translate the request's tool list into Anthropic's `tools:` array.
11	///
12	/// With `native_tool_types` on, a tool that declares a provider tool type for
13	/// [`PROVIDER_ID`] becomes the typed entry: its `params`, then `type` and
14	/// `name`. No description or schema is sent. Other tools get the generic
15	/// entry. Cache markers are applied by `translate::cache`, not here.
16	pub(crate) fn translate_tools(defs: &[ToolDef], native_tool_types: bool) -> Value {
17	    let arr: Vec<Value> = defs
18	        .iter()
19	        .map(|t| {
20	            let typed = if native_tool_types {
21	                t.provider_types.iter().find(|p| p.provider == PROVIDER_ID)
22	            } else {
23	                None
24	            };
25	            match typed {
26	                Some(pt) => {
27	                    let mut entry = pt.params.clone();
28	                    entry.remove("cache_control");
29	                    entry.insert("type".to_owned(), Value::String(pt.type_name.clone()));
30	                    entry.insert("name".to_owned(), Value::String(t.name.clone()));
31	                    tracing::debug!(
32	                        target: "paigasus::anthropic::translate",
33	                        tool = %t.name,
34	                        r#type = %pt.type_name,
35	                        "typed tool entry",
36	                    );
37	                    Value::Object(entry)
38	                }
39	                None => json!({
40	                    "name": t.name,
