1	use crate::{Scenario, Violation};
2	use paigasus_helikon_core::{ModelError, ModelEvent};
3	
4	/// Classify the first contract violation in `events`, if any.
5	///
6	/// Rules overlap by construction — a `Usage` after `Finish` breaks both
7	/// assertion 2 and assertion 1 — so the order here is part of the contract, not
8	/// an implementation detail. Two overlaps among assertions 3 to 7 are worth
9	/// calling out: cancellation (assertion 5) is checked before the stop-reason
10	/// and error rules (3, 4, 6) because a cancelled stream's stop-reason
11	/// expectation is moot; and assertion 3 explicitly excludes streams carrying
12	/// an `Err` or a cancellation, because assertion 6 governs the former and
13	/// assertion 5 governs the latter, and both demand the opposite outcome —
14	/// withholding `Finish` is exactly what the contract requires of a cancelled
15	/// stream.
16	pub fn classify(
17	    events: &[Result<ModelEvent, ModelError>],
18	    scenario: Scenario,
19	    cancelled: bool,
20	) -> Option<Violation> {
21	    let finish_at = events
22	        .iter()
23	        .position(|e| matches!(e, Ok(ModelEvent::Finish { .. })));
24	
25	    if let Some(idx) = finish_at {
26	        let after = &events[idx + 1..];
27	        if after
28	            .iter()
29	            .any(|e| matches!(e, Ok(ModelEvent::Finish { .. })))
30	        {
31	            return Some(Violation::DuplicateFinish);
32	        }
33	        if after
34	            .iter()
35	            .any(|e| matches!(e, Ok(ModelEvent::Usage { .. })))
36	        {
37	            return Some(Violation::UsageAfterFinish);
38	        }
39	        if !after.is_empty() {
40	            return Some(Violation::EventAfterFinish);
41	        }
42	    }
43	
44	    let has_finish = finish_at.is_some();
45	    let err_at = events.iter().position(Result::is_err);
46	
47	    // Assertion 5: a cancelled stream must not emit Finish. Checked before
48	    // 3/4/6 because cancellation makes the scenario's stop-reason expectation
49	    // moot.
50	    if cancelled && has_finish {
51	        return Some(Violation::FinishOnCancel);
52	    }
53	
54	    // Assertion 6: a mid-stream error must not be followed by a clean Finish.
55	    if finish_at.zip(err_at).is_some_and(|(f, e)| f > e) {
56	        return Some(Violation::FinishAfterError);
57	    }
58	
59	    // Assertion 4: a Finish must never appear when the scenario expects no
60	    // stop reason to be observed.
61	    if !scenario.expects_stop_reason() && has_finish {
62	        return Some(Violation::FinishOnTruncation);
63	    }
64	
65	    // Assertion 3: when a stop reason is expected and the stream ended
66	    // without an error or a cancellation, end-of-stream with no Finish is a
67	    // violation. The no-`Err` guard matters: assertion 6 governs the error
68	    // case and requires the opposite outcome. The no-`cancelled` guard
69	    // matters for the same reason: assertion 5 governs the cancelled case,
70	    // and withholding `Finish` is exactly what the contract requires there.
71	    if scenario.expects_stop_reason() && err_at.is_none() && !cancelled && !has_finish {
72	        return Some(Violation::MissingFinish);
73	    }
74	
75	    // Assertion 7: each call_id must carry exactly one name-bearing delta —
76	    // not "at most one". A translator that never emits a name for a call_id
77	    // satisfies "at most one" while still producing a tool call that resolves
78	    // to nothing on replay, which is precisely the bug this rule exists to
79	    // catch. Groups are built preserving first-seen `call_id` order so the
80	    // reported violation is deterministic.
81	    //
82	    // A blank `call_id` is graded differently: it needs at least one name,
83	    // not exactly one. An empty id cannot identify a call, so translators
84	    // refuse to merge parallel blank-id calls, and each such call carries
85	    // its own name under "" (SMA-566, SMA-616, SMA-617). Two names under ""
86	    // are therefore what the `ModelEvent::ToolCallDelta` contract requires
87	    // for two blank-id calls, and this assertion must not reject them.
88	    // A blank-id group with no name at all is still a translator defect.
89	    // Whether to refuse the resulting ambiguous turn is a consumer
90	    // decision, not a translator one: `ModelTurnAccumulator::finish()` in
91	    // `core` makes it, and core's `model_turn_tests` pin it (SMA-621).
92	    let mut name_counts: Vec<(String, usize)> = Vec::new();
93	    for event in events {
94	        if let Ok(ModelEvent::ToolCallDelta { call_id, name, .. }) = event {
95	            match name_counts.iter_mut().find(|(id, _)| id == call_id) {
96	                Some((_, count)) => {
97	                    if name.is_some() {
98	                        *count += 1;
99	                    }
100	                }
101	                None => name_counts.push((call_id.clone(), usize::from(name.is_some()))),
102	            }
103	        }
104	    }
105	    for (call_id, count) in &name_counts {
106	        let conforms = if call_id.is_empty() {
107	            // The "at least one" rule cannot detect a translator that
108	            // emits the name twice for ONE blank-id call.
109	            // `ModelTurnAccumulator::finish()` refuses that stream loudly
110	            // at runtime, so no call is lost silently.
111	            *count >= 1
112	        } else {
113	            *count == 1
114	        };
115	        if !conforms {
116	            return Some(Violation::ToolNameNotExactlyOnce {
117	                call_id: call_id.clone(),
118	                count: *count,
119	            });
120	        }
121	    }
122	
123	    // Assertion 8: call-scoped provider data must name a call that the stream
124	    // streamed. A `ProviderData` event with `call_id: Some(id)` and no
125	    // `ToolCallDelta` for `id` could never attach to a tool call on replay.
126	    // Provider data without a `call_id` is not call-scoped and always passes.
127	    for event in events {
128	        if let Ok(ModelEvent::ProviderData {
129	            call_id: Some(call_id),
130	            ..
131	        }) = event
132	        {
133	            if !name_counts.iter().any(|(id, _)| id == call_id) {
134	                return Some(Violation::ProviderDataUnknownCall {
135	                    call_id: call_id.clone(),
136	                });
137	            }
138	        }
139	    }
140	
141	    None
142	}
