195	
196	    /// A conforming clean stop has no violation.
197	    #[test]
198	    fn clean_stop_conforms() {
199	        let evs = vec![token("hi"), usage(), finish()];
200	        assert_eq!(classify(&evs, Scenario::CleanStop, false), None);
201	    }
202	
203	    fn tool(call_id: &str, name: Option<&str>, args: &str) -> Result<ModelEvent, ModelError> {
204	        Ok(ModelEvent::ToolCallDelta {
205	            call_id: call_id.into(),
206	            name: name.map(str::to_owned),
207	            args_delta: args.into(),
208	        })
