1	//! [`AnthropicModelBuilder`] — fluent constructor for [`crate::AnthropicModel`].
2	
3	use paigasus_helikon_core::ModelCapabilities;
4	use reqwest::Url;
5	
6	use crate::capabilities::{self, ModelEntry};
7	use crate::settings::{CacheStrategy, ExtendedThinking};
8	
9	const DEFAULT_BASE_URL: &str = "https://api.anthropic.com";
10	const DEFAULT_ANTHROPIC_VERSION: &str = "2023-06-01";
11	
12	/// Construction-time errors. Runtime errors flow through
13	/// [`paigasus_helikon_core::ModelError`].
14	#[derive(Debug, thiserror::Error)]
15	#[non_exhaustive]
16	pub enum BuildError {
17	    /// `ANTHROPIC_API_KEY` was unset and no explicit auth was supplied.
18	    #[error("ANTHROPIC_API_KEY not set in environment")]
19	    MissingApiKey,
20	    /// `base_url` failed to parse as a URL.
21	    #[error("invalid base URL: {0}")]
22	    InvalidBaseUrl(String),
23	    /// Explicit auth credential (api_key / bearer / `ANTHROPIC_API_KEY`)
24	    /// resolved to an empty (or whitespace-only) string.
25	    #[error("auth credential cannot be empty")]
26	    EmptyAuthCredential,
27	}
28	
29	#[derive(Debug, Clone)]
30	enum AuthSource {
31	    Env,
32	    ApiKey(String),
33	    Bearer(String),
34	}
35	
36	/// Resolved configuration handed off to [`crate::AnthropicModel`].
37	#[derive(Debug, Clone)]
38	pub(crate) struct Config {
39	    pub(crate) model_id: String,
40	    pub(crate) base_url: String,
41	    pub(crate) auth_header: AuthHeader,
42	    pub(crate) anthropic_version: String,
43	    pub(crate) anthropic_beta: Option<String>,
44	    pub(crate) cache_strategy: CacheStrategy,
45	    pub(crate) native_tool_types: bool,
46	    pub(crate) extended_thinking: ExtendedThinking,
47	    pub(crate) top_k: Option<u32>,
48	    pub(crate) max_output_default: u32,
49	    pub(crate) capabilities: ModelCapabilities,
50	    pub(crate) http: reqwest::Client,
51	}
52	
53	/// One of `x-api-key: <key>` or `authorization: Bearer <token>`.
54	#[derive(Debug, Clone)]
55	pub(crate) enum AuthHeader {
56	    ApiKey(String),
57	    Bearer(String),
58	}
59	
60	/// Fluent builder for [`crate::AnthropicModel`].
61	#[derive(Debug, Clone)]
62	pub struct AnthropicModelBuilder {
63	    model_id: String,
64	    auth: AuthSource,
65	    base_url: Option<String>,
66	    anthropic_version: Option<String>,
67	    beta_headers: Vec<String>,
68	    http_client: Option<reqwest::Client>,
69	    cache_strategy: CacheStrategy,
70	    native_tool_types: bool,
71	    extended_thinking: ExtendedThinking,
72	    top_k: Option<u32>,
73	    capabilities_override: Option<ModelCapabilities>,
74	}
75	
76	impl AnthropicModelBuilder {
77	    pub(crate) fn new(model_id: impl Into<String>) -> Self {
78	        Self {
79	            model_id: model_id.into(),
80	            auth: AuthSource::Env,
81	            base_url: None,
82	            anthropic_version: None,
83	            beta_headers: Vec::new(),
84	            http_client: None,
85	            cache_strategy: CacheStrategy::None,
86	            native_tool_types: true,
87	            extended_thinking: ExtendedThinking::Disabled,
88	            top_k: None,
89	            capabilities_override: None,
90	        }
91	    }
92	
93	    /// Use the given API key. Last-set auth wins.
94	    pub fn api_key(mut self, key: impl Into<String>) -> Self {
95	        self.auth = AuthSource::ApiKey(key.into());
96	        self
97	    }
98	
99	    /// Use a pre-minted bearer token (Bedrock/Vertex proxy). Last-set auth wins.
100	    pub fn bearer(mut self, token: impl Into<String>) -> Self {
101	        self.auth = AuthSource::Bearer(token.into());
102	        self
103	    }
104	
105	    /// Override the base URL. Default: `https://api.anthropic.com`.
106	    pub fn base_url(mut self, url: impl Into<String>) -> Self {
107	        self.base_url = Some(url.into());
108	        self
109	    }
110	
111	    /// Override the `anthropic-version` header. Default: `"2023-06-01"`.
112	    pub fn anthropic_version(mut self, v: impl Into<String>) -> Self {
113	        self.anthropic_version = Some(v.into());
114	        self
115	    }
116	
117	    /// Append a value to the `anthropic-beta` header. Multiple calls
118	    /// accumulate; rendered as a comma-separated list at `build()`.
119	    pub fn beta(mut self, header: impl Into<String>) -> Self {
120	        self.beta_headers.push(header.into());
121	        self
122	    }
123	
124	    /// Use a caller-provided `reqwest::Client`.
125	    pub fn http_client(mut self, c: reqwest::Client) -> Self {
126	        self.http_client = Some(c);
127	        self
128	    }
129	
130	    /// Prompt-caching strategy. Default: [`CacheStrategy::None`].
131	    pub fn cache_strategy(mut self, s: CacheStrategy) -> Self {
132	        self.cache_strategy = s;
133	        self
134	    }
135	
136	    /// Send the Anthropic typed tool entry for a tool that declares a
137	    /// provider tool type for [`PROVIDER_ID`](crate::PROVIDER_ID). Default:
138	    /// `true`. Set `false` to always send the generic entry (name,
139	    /// description and input schema) and ignore declared provider types.
140	    pub fn native_tool_types(mut self, enabled: bool) -> Self {
141	        self.native_tool_types = enabled;
142	        self
143	    }
144	
145	    /// Extended-thinking configuration. Default: [`ExtendedThinking::Disabled`].
146	    pub fn extended_thinking(mut self, t: ExtendedThinking) -> Self {
147	        self.extended_thinking = t;
148	        self
149	    }
150	
151	    /// Set the `top_k` sampling parameter. Anthropic-specific.
152	    pub fn top_k(mut self, k: u32) -> Self {
153	        self.top_k = Some(k);
154	        self
155	    }
156	
157	    /// Override the capability snapshot. Wins over the built-in lookup.
158	    pub fn with_capabilities(mut self, c: ModelCapabilities) -> Self {
159	        self.capabilities_override = Some(c);
160	        self
161	    }
162	
163	    /// Resolve auth, validate base URL, look up capabilities, materialize the
164	    /// internal [`Config`].
165	    pub(crate) fn build_config(self) -> Result<Config, BuildError> {
166	        let auth_header = match &self.auth {
167	            AuthSource::Env => {
168	                let key =
169	                    std::env::var("ANTHROPIC_API_KEY").map_err(|_| BuildError::MissingApiKey)?;
170	                if key.trim().is_empty() {
171	                    return Err(BuildError::EmptyAuthCredential);
172	                }
173	                AuthHeader::ApiKey(key)
174	            }
175	            AuthSource::ApiKey(k) => {
176	                if k.trim().is_empty() {
177	                    return Err(BuildError::EmptyAuthCredential);
178	                }
179	                AuthHeader::ApiKey(k.clone())
180	            }
181	            AuthSource::Bearer(t) => {
182	                if t.trim().is_empty() {
183	                    return Err(BuildError::EmptyAuthCredential);
184	                }
185	                AuthHeader::Bearer(t.clone())
186	            }
187	        };
188	
189	        let base_url = self.base_url.unwrap_or_else(|| DEFAULT_BASE_URL.to_owned());
190	        if Url::parse(&base_url).is_err() {
191	            return Err(BuildError::InvalidBaseUrl(base_url));
192	        }
193	
194	        let entry: ModelEntry = capabilities::lookup(&self.model_id);
195	        let capabilities = self.capabilities_override.unwrap_or(entry.caps);
196	
197	        let anthropic_beta = if self.beta_headers.is_empty() {
198	            None
199	        } else {
200	            Some(self.beta_headers.join(","))
201	        };
202	
203	        let http = self.http_client.unwrap_or_default();
204	
205	        Ok(Config {
206	            model_id: self.model_id,
207	            base_url,
208	            auth_header,
209	            anthropic_version: self
210	                .anthropic_version
